#include <iostream>
class Counter {
    int value{0};
public:
    bool add(int amount) {
        if (amount < 0 || amount > 3 - value) return false;
        value += amount;
        return true;
    }
    int get() const { return value; }
};
int main() {
    Counter c;
    std::cout << std::boolalpha << c.add(2) << '\n';
    std::cout << c.add(2) << '\n' << c.get() << '\n';
}

